<?php require __DIR__.'/../includes/functions.php'; require_login('student'); if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$b=trim($_POST['body']??'');if($b){$categories=['general','education','counseling','health','family','urgent'];$category=$_POST['category']??'general';if(!in_array($category,$categories,true))$category='general';$urgent=($category==='urgent'||!empty($_POST['is_urgent']))?1:0;db()->prepare("INSERT INTO messages(student_id,sender_role,body,category,is_urgent) VALUES(?, 'student', ?, ?, ?)")->execute([user()['id'],$b,$category,$urgent]);audit('message_sent','message',null,$category);flash('پیام شما ارسال شد.');redirect('/student/index.php');}} layout_start('پیام جدید'); ?><div class="card narrow"><h1>ارسال پیام به مدیر</h1><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>موضوع پیام<select name="category"><option value="general">عمومی</option><option value="education">آموزشی</option><option value="counseling">مشاوره‌ای</option><option value="health">سلامت</option><option value="family">خانوادگی</option><option value="urgent">نیازمند توجه سریع</option></select></label><label>متن پیام<textarea name="body" rows="8" required></textarea></label><label class="checkbox"><input type="checkbox" name="is_urgent" value="1"> این پیام نیازمند توجه سریع است.</label><button class="button">ارسال پیام</button><a href="<?=e(url('/student/index.php'))?>" class="button secondary">انصراف</a></form></div><?php layout_end(); ?>
